import {ImageAssistant} from './textile-tools-ai.js';
import {imageThumbnail,imageFromResult} from './textile-ai-images.js';
import {imageBlob,saveBlob} from './textile-tools-image.js';
const specs={
  extract:{image:true,title:'AI 提取平面花型',button:'AI 提取花型',brief:'提取主体印花，尽量保留花朵形状、颜色与疏密，去除实拍背景、光影和褶皱干扰。',note:'上传实拍后可先选四角。AI 会尝试还原平面花稿，遮挡与严重褶皱处仍需核对。',prompt:brief=>'Extract a flat 2D textile print swatch from image 1. It shows the selected fabric area, possibly perspective-corrected. Preserve the visible motif geometry, original colors, motif sizes, spacing and print character. Remove room/product context, seams, highlights, shadows and fabric fold shading where possible. Do not add bedding, borders, labels, logos or invent additional motifs. If content is occluded, continue only clearly evidenced repeats conservatively. Return a flat textile print artwork, not a photograph. User brief: '+brief},
  repeat:{image:true,title:'AI 修复循环接缝',button:'AI 修复接缝',brief:'修复中心十字处的拼接断口，延续附近已有纹样和底色，保持其他花型不变。',note:'系统先把四边移到画面中央供 AI 修补，再移回并铺开检查。外围和非接缝区域由原稿保留。',prompt:brief=>'Image 1 is a textile pattern offset by half its width and height, so the ORIGINAL tile seams are now the CENTER vertical and horizontal cross. Repair discontinuities ONLY in a narrow central cross within 14% of center each way. Preserve all original motifs, scale, print colors and spacing outside that repair. Keep the outer 7% border exactly unchanged. Extend cut motif contours using adjacent evidence; do not redraw the entire pattern, impose mirror symmetry, add frames, text or mockups. Return the whole offset tile with identical framing. User brief: '+brief},
  recolor:{kind:'palette',title:'AI 设计系列配色',button:'AI 推荐三组配色',brief:'适合春夏家纺的低饱和配色，背景轻盈，主体花卉清楚，提供三种不同方向。',note:'AI 根据花型和你的方向提出配色。采用方案后按原有像素换色，可继续精调匹配范围。'},
  board:{kind:'moodboard',title:'AI 策划搭配提案',button:'AI 规划搭配方案',brief:'根据这些花型、面料和空间参考，安排主次、图片顺序、搭配色与提案说明，形成协调的家纺系列。',note:'AI 阅读已上传素材，给出可修改的搭配与排版建议；确认后应用到搭配板。'},
  delivery:{kind:'delivery',title:'AI 上架适配建议',button:'AI 分析交付方案',brief:'用于电商商品上架，主体完整、花型细节清楚，优先控制文件体积，请推荐比例、留白、尺寸和格式。',note:'AI 根据用途和参考图片推荐交付参数。采用后本机批量处理，原文件保留。'},
  copy:{kind:'copy',title:'AI 撰写商品文案',button:'AI 生成文案',brief:'围绕已确认的商品信息，写清晰、有吸引力且适合上架的标题、卖点和介绍。不要补造未知材质、尺寸、认证或功能。',note:'先填写下面的真实商品信息；AI 负责组织表达，不从图片猜测规格和功效。'}
};
const textElement=(tag,text,className)=>{const element=document.createElement(tag);element.textContent=text;if(className)element.className=className;return element;};
export function attachToolAI(tool,state){
  const spec=specs[tool.id];if(!spec)return;
  const settings=state.element.querySelector('.tt-settings'),manualHeading=settings.querySelector('h2');if(manualHeading)manualHeading.textContent=tool.id==='copy'?'商品信息与手动整理':'手动精修与导出';
  const card=document.createElement('section');card.className='tt-ai-card';card.innerHTML=`<span class="tt-ai-eyebrow">AI CREATIVE ASSISTANT</span><h2>${spec.title}</h2><label class="tt-field"><span>${tool.id==='delivery'?'使用平台与交付目的':'创作方向 · 可以修改'}</span><textarea class="tt-ai-brief" maxlength="2000" aria-label="AI ${spec.title}要求"></textarea></label><button class="tt-primary tt-ai-start" type="button">${spec.button}</button>${spec.image?'<div class="tt-inline-buttons"><button class="tt-secondary tt-ai-check" type="button">检查任务</button><button class="tt-secondary tt-ai-cancel" type="button">停止任务</button></div>':''}<p class="tt-ai-note"></p><p class="tt-ai-charge">点击 AI 按钮后，将参考图与要求交给当前配置的服务，按服务计费。</p><p class="tt-status tt-ai-status" role="status" aria-live="polite"></p>`;
  settings.prepend(card);const brief=card.querySelector('textarea'),start=card.querySelector('.tt-ai-start'),feedback=card.querySelector('.tt-ai-status');brief.value=spec.brief;card.querySelector('.tt-ai-note').textContent=spec.note;
  const choose=textElement('button',tool.id==='copy'?'填写商品真实信息 ↓':'＋ 上传 AI 参考素材','tt-secondary tt-ai-upload');choose.type='button';choose.onclick=()=>{if(state.aiBusy)return;if(tool.id==='copy'){document.getElementById('copyName').scrollIntoView({block:'center'});document.getElementById('copyName').focus();}else document.getElementById(tool.id+'Choose')?.click();};card.querySelector('h2').after(choose);
  const results=document.createElement('section');results.className='tt-ai-results';results.hidden=true;state.element.querySelector('.tt-preview-head').after(results);
  const setStatus=(message,error=false)=>{feedback.textContent=message;feedback.dataset.error=String(error);};
  let revision=0,sourceSnapshot=null,candidate=null,assistant,planning=null,priorDisabled=new Map();
  function hasSource(){return tool.id==='copy'||!!state.source||!!state.aiHasSource?.();}
  function busy(value){state.aiBusy=value;start.disabled=value||!hasSource();brief.disabled=value;choose.disabled=value;
    if(value){priorDisabled=new Map();state.element.querySelectorAll('input,select,button,textarea').forEach(control=>{if(card.contains(control)||results.contains(control))return;priorDisabled.set(control,control.disabled);control.disabled=true;});}
    else{for(const [control,disabled]of priorDisabled)if(control.isConnected)control.disabled=disabled;priorDisabled.clear();}
  }
  state.notifySource=()=>{revision++;candidate=null;results.hidden=true;results.replaceChildren();state.element.querySelector('.tt-stage,.tt-copy-preview')?.removeAttribute('hidden');start.disabled=state.aiBusy||!hasSource();setStatus('素材已就绪，点击 AI 获取方案。');};
  async function inputImages(){const sources=state.aiImages?await state.aiImages():state.source?[state.source]:[];if(tool.id!=='copy'&&!sources.length)throw Error('请先上传参考图片');return sources.slice(0,6).map(source=>imageThumbnail(source));}
  function appendHeading(title,note){results.replaceChildren(textElement('strong',title,'tt-ai-result-title'));if(note)results.append(textElement('p',note,'tt-ai-result-note'));results.hidden=false;}
  function adoptButton(label,action){const button=textElement('button',label,'tt-primary tt-ai-adopt');button.type='button';button.onclick=async()=>{if(state.aiBusy||button.disabled)return;button.disabled=true;try{await action();setStatus('AI 方案已采用，可以继续手动精修或导出。');results.classList.add('is-adopted');results.querySelectorAll('.tt-ai-adopt').forEach(control=>control.disabled=true);const restore=results.querySelector('.tt-ai-restore');if(restore)restore.disabled=false;state.element.querySelector('.tt-stage,.tt-copy-preview')?.removeAttribute('hidden');}catch(error){button.disabled=false;setStatus(error.message,true);}};return button;}
  function showPlan(plan){
    appendHeading('AI 方案 · 确认后应用',plan.summary||plan.reason||'依据当前素材与已填写信息生成。');
    if(spec.kind==='palette'){
      const list=document.createElement('div');list.className='tt-ai-palette-options';plan.palettes.forEach((palette,index)=>{const option=document.createElement('article');option.append(textElement('h3',palette.name));const swatches=document.createElement('div');swatches.className='tt-ai-swatches';palette.colors.forEach(color=>{const swatch=document.createElement('span');swatch.style.background=color;swatch.title=color;swatches.append(swatch);});option.append(swatches,textElement('p',palette.reason),adoptButton('采用这组配色',()=>state.applyAIPlan(plan,index)));list.append(option);});results.append(list);
    }else if(spec.kind==='copy'){
      const output=document.createElement('textarea');output.readOnly=true;output.setAttribute('aria-label','AI 文案候选');output.className='tt-ai-copy-candidate';output.value='标题\n'+plan.titles.join('\n')+'\n\n卖点\n'+plan.bullets.join('\n')+'\n\n介绍\n'+plan.body;results.append(output,adoptButton('采用 AI 文案',()=>state.applyAIPlan(plan)));
    }else{
      const details=document.createElement('dl');const rows=spec.kind==='moodboard'?[['提案标题',plan.title],['搭配说明',plan.note],['素材顺序',plan.order.map(index=>index+1).join(' → ')],['排列方式',plan.layout==='focus'?'主图与细节':'等分排列']]:[['推荐比例',plan.ratio==='source'?'保留原比例':plan.ratio],['调整方式',plan.fit==='contain'?'完整保留主体，补白':'居中裁剪'],['导出格式',plan.format.replace('image/','').toUpperCase()],['最长边',plan.maxEdge+' px'],['质量',plan.quality+'%']];rows.forEach(([name,value])=>details.append(textElement('dt',name),textElement('dd',value)));results.append(details,adoptButton(spec.kind==='moodboard'?'采用 AI 搭配方案':'应用 AI 参数，再批量处理',()=>state.applyAIPlan(plan)));
    }
    if(state.restoreBeforeAI){const restore=textElement('button','撤回本次 AI 方案','tt-secondary tt-ai-restore');restore.disabled=true;restore.onclick=()=>{state.restoreBeforeAI();restore.disabled=true;results.classList.remove('is-adopted');results.querySelectorAll('.tt-ai-adopt').forEach(control=>control.disabled=false);setStatus('已恢复采用前的设置。');};results.append(restore);}
  }
  async function showImage(url,{isCurrent=()=>true}={}){
    const original=sourceSnapshot||await imageFromResult(url.replace(/\/images\/[a-f0-9-]{36}$/,'/images/original'));const generated=await imageFromResult(url);if(!isCurrent())return;const processed=state.processAIImage?await state.processAIImage(generated,original):generated;if(!isCurrent())return;candidate=processed;
    appendHeading('AI 花稿候选 · 先对比再采用','检查纹样、颜色与边缘。采用前不会替换当前结果。');const compare=document.createElement('div');compare.className='tt-ai-image-compare';for(const [label,image]of [['处理前',state.aiComparisonImage?state.aiComparisonImage(original):original],['AI 处理候选',candidate]]){const figure=document.createElement('figure'),picture=document.createElement('img');picture.src=imageThumbnail(image,1200);picture.alt=label;figure.append(picture,textElement('figcaption',label+' · '+image.width+' × '+image.height+' px'));compare.append(figure);}results.append(compare,adoptButton('采用 AI 结果并继续编辑',async()=>{await state.applyAIImage(candidate);results.classList.add('is-adopted');}));const download=textElement('button','下载 AI 候选 PNG','tt-secondary');download.onclick=async()=>{try{saveBlob(await imageBlob(candidate),tool.name+'_AI候选.png');}catch(error){setStatus(error.message,true);}};const dismiss=textElement('button','收起候选，保留原稿','tt-secondary');dismiss.onclick=()=>{results.hidden=true;state.element.querySelector('.tt-stage,.tt-copy-preview')?.removeAttribute('hidden');};results.append(download,dismiss);state.element.querySelector('.tt-stage')?.setAttribute('hidden','');
  }
  if(spec.image){assistant=new ImageAssistant({storageKey:'zhijing-tool-ai-'+tool.id+'-v1',status:setStatus,result:showImage,busy});card.querySelector('.tt-ai-check').onclick=()=>assistant.check();card.querySelector('.tt-ai-cancel').onclick=()=>assistant.cancel();}
  start.onclick=async()=>{
    if(state.aiBusy)return;const intent=brief.value.trim()||spec.brief;if(intent.length>2000)return setStatus('请将创作要求控制在 2000 字以内',true);const requestRevision=revision;results.classList.remove('is-adopted');
    if(spec.image){try{sourceSnapshot=state.prepareAIImage?await state.prepareAIImage():state.source;if(!sourceSnapshot)throw Error('请先上传一张参考图片');await assistant.start(imageThumbnail(sourceSnapshot,2048),spec.prompt(intent),{title:tool.name,lockPattern:tool.id!=='extract'});}catch(error){setStatus(error.message,true);}return;}
    busy(true);setStatus('AI 正在分析素材并生成方案…');planning=new AbortController();try{const images=await inputImages(),facts=state.aiFacts?.()||{};if(spec.kind==='copy'&&!facts.name?.trim())throw Error('请先在商品信息中填写商品名称');const response=await fetch('/api/textile/plan',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({kind:spec.kind,brief:intent,images,facts}),signal:AbortSignal.any([planning.signal,AbortSignal.timeout(130000)])});let value;try{value=await response.json();}catch{throw Error('AI 服务未返回可读取的方案，请稍后再试');}if(!response.ok)throw Error(value.error||'AI 方案请求失败');if(requestRevision!==revision)throw Error('参考素材已更新，请重新生成方案');showPlan(value.plan);setStatus('AI 方案已生成，确认后再应用。');}catch(error){setStatus(error.name==='TimeoutError'?'AI 分析超时，未自动重试，请稍后确认再提交。':error.message,true);}finally{planning=null;busy(false);}
  };
  start.disabled=!hasSource();if(assistant?.pending)start.disabled=true;window.addEventListener('pagehide',()=>planning?.abort());return {card,results};
}
